window.AUTH=window.AUTH||{};window.AUTH["19-309"]={"d":"19-309","id":"2020/19-309","n":"Carney v. Adams","briefs":[{"k":"petitioner","label":"Brief of petitioner John C. Carney, Governor of Delaware","date":"2020-01-21","url":"https://www.supremecourt.gov/DocketPDF/19/19-309/132933/20200213123011467_19-309%20ts%20reprint.pdf","side":"pet","n":59},{"k":"respondent","label":"Brief of respondent James R. Adams","date":"2020-02-20","url":"https://www.supremecourt.gov/DocketPDF/19/19-309/133723/20200220164406653_Brief.File.pdf","side":"res","n":84},{"k":"reply","label":"Reply of petitioner John C. Carney, Governor of Delaware","date":"2020-03-13","url":"https://www.supremecourt.gov/DocketPDF/19/19-309/138279/20200316143647509_Carney%20-%20Adams%20-%20SCT%20-%20Reply%20Br.%20-%20CORRECTED%20FINAL%20-%202.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-309_4f15.pdf","tr":true,"items":[{"t":"case","label":"Albuquerque Indian Rights v. Lujan","cite":"930 F.2d 49","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/930/49/","by":{"0":"22"}},{"t":"case","label":"Ariz. State Legislature v. Ariz. Indep. Redistricting Comm’n","cite":"135 S. Ct. 2652","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2652/","sc":1,"by":{"0":"36"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"op":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Ayotte v. Planned Parenthood of N. New Eng.","cite":"546 U.S. 320","y":2006,"id":"2005/04-1144","sc":1,"sum":"In a rare unanimous decision regarding abortion, the Supreme Court sidestepped the most contentious questions of the case and focused instead on the proper remedy when a portion of a statute is found unconstitutional.","sumSrc":"Oyez","by":{"0":"49, 50"}},{"t":"case","label":"Bernal v. Fainter","cite":"467 U.S. 216","y":1984,"id":"1983/83-630","sc":1,"sum":"Article 5949(2) violates the Equal Protection Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 37"}},{"t":"case","label":"Boyd v. Nebraska ex rel. Thayer","cite":"143 U.S. 135","y":1892,"id":"scdb/1891-107","sc":1,"sum":"Boyd was born in Ireland in 1831, of Irish parents. His father emigrated to the United States in 1844, with all his family^and settled in Ohio, in which.State he has since resided continuously. In 1849 the father duly declared his intention to become a citizen of the United States, but there is no record or other written, evidence that he ever completed his naturalization by taking 'out his naturalization …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35","2":"3"}},{"t":"case","label":"Branti v. Finkel","cite":"445 U.S. 507","y":1980,"id":"1979/78-1654","sc":1,"ar":7,"sum":"The First and Fourteenth Amendments protect respondents from discharge solely because of their political beliefs.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10–13, 16–17, 25–28, 30, 34, 36–37, 41, 46","1":"passim","2":"3–7, 20"}},{"t":"case","label":"Brockett v. Spokane Arcades, Inc.","cite":"472 U.S. 491","y":1985,"id":"1984/84-28","sc":1,"sum":"The Court of Appeals erred in facially invalidating the statute in its entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Cede & Co. v. Technicolor, Inc.","cite":"634 A.2d 345","y":1993,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/634/345/","by":{"0":"33"}},{"t":"case","label":"Chisom v. Roemer","cite":"501 U.S. 380","y":1991,"id":"1990/90-757","sc":1,"sum":"The Court determined that if Congress had that aim, it would have indicated this exclusion explicitly. Consequently, the Court favored a broad interpretation of the word \"representative\" in section 2 of the Voting Rights Act, considering it to encompass all winners of popular elections.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"20","1":"15"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"District of Columbia v. Murphy","cite":"314 U.S. 441","y":1941,"id":"scdb/1941-023","sc":1,"sum":"1. One does not acquire a domicile in the District of Columbia, within the meaning of the District of Columbia Income Tax Act, merely by coming to the Distriqt to live for an indefinite period while in the Government service.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Doherty v. Rutgers Sch. of Law-Newark","cite":"651 F.2d 893","y":1981,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/651/893/","by":{"0":"22"}},{"t":"case","label":"E.I. DuPont de Nemours & Co. v. Pressman","cite":"679 A.2d 436","y":1996,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/679/436/","sum":"Recognizing that a “public policy exception” to at-will employment is created by the common law covenant of good faith and fair dealing.","sumSrc":"brief:0","by":{"0":"33"}},{"t":"case","label":"Elrod v. Burns","cite":"427 U.S. 347","y":1976,"id":"1975/74-1520","sc":1,"ar":6,"sum":"The judgment is affirmed. Pp. 351-374; 374-375. 509 F. 2d 1133, affirmed. MR. JUSTICE BRENNAN, joined by MR. JUSTICE WHITE and MR. JUSTICE MARSHALL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10–13, 16, 25–28, 30, 34, 36, 45–46","1":"passim","2":"3–6, 20"}},{"t":"case","label":"Exec. Benefits Ins. Agency v. Arkison","cite":"573 U.S. 25","y":2014,"id":"2013/12-1200","sc":1,"sum":"The Court found that a bankruptcy judge may hear arguments and file a report with a district court for \"non-core\" bankruptcy issues.","sumSrc":"Oyez","by":{"0":"50–51"}},{"t":"case","label":"Exhaustless Inc. v. FAA","cite":"931 F.3d 1209","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/931/1209/","by":{"0":"22"}},{"t":"case","label":"Farmers for Fairness v. Kent County","cite":"940 A.2d 947","y":2008,"court":"Del. Ch.","url":"https://www.courtlistener.com/c/A.2d/940/947/","by":{"0":"51","2":"23"}},{"t":"case","label":"FEC v. Democratic Senatorial Campaign Comm.","cite":"454 U.S. 27","y":1981,"id":"1981/80-939","sc":1,"op":2,"ar":2,"sum":"Section 441a(d)(3) does not expressly or by necessary implication foreclose the use of agency agreements, such as are at issue here, and the FEC thus acted within the authority vested in it by Congress when it determined to permit such agreements.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"49–50"}},{"t":"case","label":"Gill v. Whitford","cite":"138 S. Ct. 1916","y":2018,"id":"2017/16-1161","sc":1,"sum":"A case in which the Court was asked to decide whether partisan gerrymandering claims are justiciable, but the Court held that the plaintiffs lacked judicial standing.","sumSrc":"Oyez","by":{"0":"20, 47"}},{"t":"case","label":"Governor of Del. v. Adams","cite":"914 F.3d 827","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/914/827/","by":{"0":"14"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"ar":5,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"16–17, 28–29, 31, 34–37","1":"21, 26, 27, 36","2":"3, 6–8, 15"}},{"t":"case","label":"Hechinger v. Martin","cite":"411 F. Supp. 650","y":1976,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./411/650/","by":{"0":"37","1":"34"}},{"t":"case","label":"Humphrey’s Ex’r v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Int’l Bhd. of Teamsters v. United States","cite":"431 U.S. 324","y":1977,"id":"1976/75-636","sc":1,"op":1,"sum":"The United States instituted this litigation under Title VII of the Civil Rights Act of 1964 against petitioners, a nationwide common carrier of motor freight, and a union representing a large group of the company's employees. The Government alleged that the company had engaged in a pattern or practice of discriminating against Negroes and Spanishsurnamed persons (hereinafter sometimes collectively \"minority …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"14"}},{"t":"case","label":"James B. Beam Distilling Co. v. Georgia","cite":"501 U.S. 529","y":1991,"id":"1990/89-680","sc":1,"sum":"The judgment is reversed, and the case is remanded. 259 Ga. 363, 382 S. E. 2d 95, reversed and remanded. JUSTICE SOUTER, joined by JUSTICE STEVENS, concluded that once this Court has applied a rule of law to the litigants in one case, it must do so with respect to all others not barred by procedural requirements or res judicata.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Kelty v. State Farm Mut. Auto. Ins. Co.","cite":"73 A.3d 926","y":2013,"court":"Del.","url":"https://www.courtlistener.com/c/A.3d/73/926/","by":{"0":"33"}},{"t":"case","label":"Kurowski v. Krajewski","cite":"848 F.2d 767","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/848/767/","by":{"0":"13, 31","1":"32, 33"}},{"t":"case","label":"Leavitt v. Jane L.","cite":"518 U.S. 137","y":1996,"id":"1995/95-1242","sc":1,"op":1,"sum":"The anonymous Per Curiam opinion held that the Utah Legislature had explicitly stated that each of the two abortion provisions was meant to stand independent of the other. The Court called the Tenth Circuit's interpretation of the Utah legislature's intent \"questionable when considered in isolation\" and \"plainly error\" when considered in light of the statutory text.","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"LoFrisco v. Schaffer","cite":"341 F. Supp. 743","y":1972,"url":"https://www.courtlistener.com/c/F.%20Supp./341/743/","by":{"0":"37","1":"34"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":2,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"15, 19–20, 22","1":"16","2":"1–2"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Newman v. Voinovich","cite":"986 F.2d 159","y":1993,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/986/159/","by":{"0":"13","1":"29, 30, 33"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"N. Pipeline Construction Co. v. Marathon Pipeline Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"O’Hare Truck Serv., Inc. v. City of Northlake","cite":"518 U.S. 712","y":1996,"id":"1995/95-191","sc":1,"sum":"The Court held, in an opinion by Justice Anthony Kennedy, that independent contractors, such as O'Hare Truck Service, are entitled to the same First Amendment protections as those afforded to government employees.","sumSrc":"Oyez","by":{"0":"27","1":"23, 47","2":"3, 7, 15, 21–22"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Randall v. Sorrell","cite":"548 U.S. 230","y":2006,"id":"2005/04-1528","sc":1,"sum":"The opinion by Justice Stephen Breyer held that the Court should let stand the Buckley decision and its invalidation of expenditure limits. Vermont's argument that such limits prevent candidates from spending too much time fund-raising was deemed irrelevant because it was \"perfectly obvious\" and would not have changed the result in Buckley .","sumSrc":"Oyez","by":{"0":"50"}},{"t":"case","label":"Reese v. Hartnett","cite":"73 A.2d 782","y":1950,"court":"Del. Super. Ct.","url":"https://www.courtlistener.com/c/A.2d/73/782/","by":{"0":"51"}},{"t":"case","label":"Regan v. Time, Inc.","cite":"468 U.S. 641","y":1984,"id":"1983/82-729","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 539 F. Supp. 1371, affirmed in part and reversed in part.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Reno v. ACLU","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"43, 49","2":"15"}},{"t":"case","label":"Republican Party of Minn. v. White","cite":"536 U.S. 765","y":2002,"id":"2001/01-521","sc":1,"sum":"The Court held that the announce clause violates the First Amendment. The Court reasoned that the announce clause prohibits speech based on its content and burdens a category of speech that is at the core of First Amendment freedoms - speech about the qualifications of candidates for public office.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Rutan v. Republican Party of Ill.","cite":"497 U.S. 62","y":1990,"id":"1989/88-1872","sc":1,"ar":1,"sum":"In a 5-to-4 decision, the Court held that Governor Thompson's practices amounted to an unconstitutional patronage system. The Court found that employees would feel \"a significant obligation to support political positions held by their superiors\" in lieu of their true beliefs in order to progress up the career ladder.","sumSrc":"Oyez","by":{"0":"16, 25, 27, 37, 46","1":"passim","2":"3, 21"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Shelby County v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"op":1,"sum":"The Court found that Section 4 of the Voting Rights Act was unconstitutional.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"136 S. Ct. 1540","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"0":"19, 21"}},{"t":"case","label":"Sugarman v. Dougall","cite":"413 U.S. 634","y":1973,"id":"1972/71-1222","sc":1,"sum":"The Court affirmed the District Court and held the statute unconstitutional.","sumSrc":"Oyez","by":{"0":"35","2":"3"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"49","1":"47"}},{"t":"case","label":"United States v. Playboy Entm’t Grp., Inc.","cite":"529 U.S. 803","y":2000,"id":"1999/98-1682","sc":1,"sum":"The Court held that because the Federal Government failed to show that section 505 was the least restrictive means to further its interests, requiring cable television operators to fully scramble or limit time when sexually-oriented programming was transmitted violated the First Amendment's free speech guarantee.","sumSrc":"Oyez","by":{"0":"43","2":"18"}},{"t":"case","label":"United States v. Windsor","cite":"570 U.S. 744","y":2013,"id":"2012/12-307","sc":1,"op":1,"sum":"The Court found that the Defense of Marriage Act (DOMA) was unconstitutional under the equal protection clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Ward v. Rock Against Racism","cite":"491 U.S. 781","y":1989,"id":"1988/88-226","sc":1,"sum":"The Court upheld the ordinance, giving broad deference to the government's interest in maintaining order. As long as \"the means chosen are not substantially broader than necessary to achieve the government's interest,\" a regulation will not be invalidated because a court concludes that the government's interest \"could be adequately served by some less-speech-restrictive alternative.\".","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Williams-Yulee v. Florida Bar","cite":"575 U.S. 433","y":2015,"id":"2014/13-1499","sc":1,"ar":1,"sum":"The Court held that a rule prohibiting judicial candidates from personally soliciting campaign funds does not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"17, 36, 38","2":"8, 11, 15"}},{"t":"case","label":"Zobel v. Williams","cite":"457 U.S. 55","y":1982,"id":"1981/80-1146","sc":1,"sum":"The Alaska dividend distribution plan violates the guarantees of the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"const","label":"Article IV, Section 4","clauses":[["guarantee","Guarantee Clause"]],"text":"The United States shall guarantee to every State in this Union a Republican Form of Government, and shall protect each of them against Invasion; and on Application of the Legislature, or of the Executive (when the Legislature cannot be convened) against domestic Violence.","by":{"0":"3, 35"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"3","1":"passim","2":"1, 3, 7–8, 15, 19, 22"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"0":"4","2":"3"}},{"t":"case","label":"44 Liquormart, Inc. v. Rhode Island","cite":"517 U.S. 484","y":1996,"id":"1995/94-1140","sc":1,"sum":"In a fractious opinion for a unanimous Court, Justice Stevens found Rhode Island's statutory ban on liquor price advertising to be an unconstitutional infringement of the liquor sellers' First Amendment right to freedom of speech.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Acevedo-Delgado v. Rivera","cite":"292 F.3d 37","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/292/37/","by":{"1":"33"}},{"t":"case","label":"Adams v. Governor of Delaware","cite":"922 F.3d 166","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/922/166/","op":2,"by":{"1":"passim"}},{"t":"case","label":"Arizona State Legislature v. Arizona Independent Redistricting Comm’n","cite":"135 S. Ct. 2652","y":2015,"id":"2014/13-1314","sc":1,"sum":"The Court determined that the Elections Clause of the U.S. Constitution does not prohibit a state from creating an independent redistricting commission by initiative.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Ashcroft v. American Civil Liberties Union","cite":"542 U.S. 656","y":2005,"id":"2003/03-218","sc":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"1":"43","2":"18"}},{"t":"case","label":"Assaf v. Fields","cite":"178 F.3d 170","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/178/170/","by":{"1":"24"}},{"t":"case","label":"Baird v. State Bar of Ariz.","cite":"401 U.S. 1","y":1971,"id":"1970/15","sc":1,"sum":"The Court held that the First Amendment protection of freedom of association prevents a state from denying a person access to a profession based on the exercise of that right.","sumSrc":"Oyez","by":{"1":"22, 35, 36"}},{"t":"case","label":"Bode v. Barrett","cite":"344 U.S. 583","y":1953,"id":"scdb/1952-046","sc":1,"sum":"Scott W. Lucas, Charles A. Thomas and Hugh J. Graham, Jr. submitted on brief for appellants in No. 187.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Bogart v. Vermilion County, Illinois","cite":"909 F.3d 210","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/909/210/","by":{"1":"26"}},{"t":"case","label":"Brown v. Entertainment Merchants Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Cadle Co. v. Hayes","cite":"116 F.3d 957","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/116/957/","by":{"1":"18"}},{"t":"case","label":"Camacho v. Brandon","cite":"317 F.3d 153","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/317/153/","by":{"1":"33"}},{"t":"case","label":"Chandler v. Miller","cite":"520 U.S. 305","y":1997,"id":"1996/96-126","sc":1,"sum":"The Court held, however, that Georgia's statute did not fall in this exceptional category, since it failed to show why its desire to avoid drug users in its high political offices should outweigh candidates' privacy interests.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Common Cause Indiana v. Individual Members of the Indiana Election Commission","cite":"800 F.3d 913","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/800/913/","op":3,"ar":1,"by":{"1":"41, 42","2":"21"}},{"t":"case","label":"Dickeson v. Quarberg","cite":"844 F.2d 1435","y":1988,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/844/1435/","by":{"1":"26"}},{"t":"case","label":"Dothard v. Rawlinson","cite":"433 U.S. 321","y":1977,"id":"1976/76-422","sc":1,"sum":"The Supreme Court held that the height and weight requirements violated Title VII because Rawlinson showed that the requirement excluded 41% of females in the nation, and the Department was unable to show that the requirement was job-related. The “contact position” ban was a bona fide occupational qualification, however, so Title VII did not prohibit it.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Elfbrandt v. Russell","cite":"384 U.S. 11","y":1966,"id":"1965/656","sc":1,"sum":"1. -Political grotps may embrace both legal and illegal aims, and one may join such groups without embracing the latter.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"F.C.C. v. WNCN Listeners Guild","cite":"450 U.S. 582","y":1991,"id":"1980/79-824","sc":1,"sum":"The FCC's Policy Statement is not inconsistent with the Act and is a constitutionally permissible means of implementing the Act's publicinterest standard.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Faughender v. City of North Olmsted, Ohio","cite":"927 F.2d 909","y":1991,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/927/909/","by":{"1":"34"}},{"t":"case","label":"Fazio v. City and County of San Francisco","cite":"125 F.3d 1328","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/125/1328/","by":{"1":"27"}},{"t":"case","label":"Federal Election Comm’n v. NRA Political Victory Fund","cite":"513 U.S. 88","y":1994,"id":"1994/93-1151","sc":1,"sum":"Petitioner Federal Election Commission (FEC) brought this civil action against respondents seeking to enforce a provision of the Federal Election Campaign Act of 1971 (FECA). The District Court ruled against respondents. The Court of Appeals reversed and entered its judgment on October 22, 1993. Without first seeking or obtaining the Solicitor General's authorization, the FEC filed in its own name a petition for a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Environmental Services (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"op":1,"ar":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Galli v. New Jersey Meadowlands Comm’n","cite":"490 F.3d 265","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/490/265/","by":{"1":"23"}},{"t":"case","label":"Greer v. City of Wichita, Kansas","cite":"943 F.3d 1320","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/1320/","by":{"1":"18"}},{"t":"case","label":"Hagan v. Quinn","cite":"867 F.3d 816","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/816/","by":{"1":"27"}},{"t":"case","label":"Hoover v. Ronwin","cite":"466 U.S. 558","y":1984,"id":"1983/82-1474","sc":1,"sum":"The District Court properly dismissed the complaint for failure to state a claim on which relief could be granted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Horton v. Taylor","cite":"767 F.2d 471","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/767/471/","by":{"1":"24"}},{"t":"case","label":"Howard v. N.J. Dept. of Civil Service","cite":"667 F.2d 1099","y":1981,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/667/1099/","by":{"1":"15"}},{"t":"case","label":"Isaacs v. Messick","cite":"40 A. 1109","y":1894,"court":"Del. Super.","url":"https://www.courtlistener.com/c/A./40/1109/","by":{"1":"19"}},{"t":"case","label":"Janus v. American Federation of State, County, and Mun. Employees, Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Keyishian v. Board of Regents of University of State of N. Y.","cite":"385 U.S. 589","y":1967,"id":"1966/105","sc":1,"sum":"The Court held that the provisions of the New York plan were defined in such uncertain terms that they infringed upon the constitutional rights of public servants.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Knight v. Vernon","cite":"214 F.3d 544","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/214/544/","by":{"1":"26"}},{"t":"case","label":"Knox v. Service Employees Intern. Union, Local 1000","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Laird v. Tatum","cite":"408 U.S. 1","y":1972,"id":"1971/71-288","sc":1,"sum":"Respondents' claim that their First Amendment rights are chilled, due to the mere existence of this data-gathering system, does not constitute a justiciable controversy on the basis of the record in this case, disclosing as it does no showing of objective harm or threat of specific future harm. Pp. 3-16. 144 U. S. App. D. C. 72, 444 F. 2d 947, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Lehner v. O’Rourke","cite":"339 F. Supp. 309","y":1971,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./339/309/","by":{"1":"30"}},{"t":"case","label":"MacGuire v. Houston","cite":"717 P.2d 948","y":1986,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/717/948/","by":{"1":"30"}},{"t":"case","label":"Martin v. United States","cite":"889 F.3d 827","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/889/827/","by":{"1":"18"}},{"t":"case","label":"Moog Indust. v. Federal Trade Comm’n","cite":"355 U.S. 411","y":1950,"id":"1957/77","sc":1,"sum":"The question whether a valid order of the Federal Trade Commission, directing one firm to cease and desist from engaging in illegal price discrimination in violation of § 2 of the Clayton Act, should go into effect before competing firms are similarly restrained is for deter mination by the Commission; it should be considered by a reviewing court only if raised before the Commission; and a deternination of it by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Murphy v. National Collegiate Athletic Ass’n","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"1":"53","2":"23"}},{"t":"case","label":"New State Ice Co. v. Liebmann","cite":"285 U.S. 262","y":1932,"id":"scdb/1931-090","sc":1,"sum":"repugnant to the due process clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"New York City Transit Authority v. Beazer","cite":"440 U.S. 568","y":1979,"id":"1978/77-1427","sc":1,"sum":"The Court reversed the Second Circuit and held that the Transit Authority's policy was not unconstitutional or illegal under the Civil Rights Act. Writing for the majority, Justice Stevens described Beazer's statistical argument as \"weak\", as the 81 percent statistic did not relate to methadone users specifically.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Newman v. Voinovich","cite":"789 F. Supp. 1410","y":1992,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./789/1410/","by":{"1":"32"}},{"t":"case","label":"Nixon v. Shrink Missouri Government PAC","cite":"528 U.S. 377","y":2000,"id":"1999/98-963","sc":1,"sum":"The Court held that Buckley is the authority for comparable state regulation and, but that the federal limits approved in Buckley, with or without adjustment for inflation, do not define the scope of permissible state limitations.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Northeastern Florida Chapter of Associated General Contractors of America v. City of Jacksonville, Fla.","cite":"508 U.S. 656","y":1993,"id":"1992/91-1721","sc":1,"op":2,"ar":1,"sum":"The majority determined that the association members' possible lack of fair opportunity as a consequence of the ordinance would have constituted injury. Since the association members would have competed for the reserved city contracts in the absence of the ordinance, the Court found that they did have standing and reversed the judgment of the Court of Appeals.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Parents Involved in Community Schools v. Seattle School Distr. No. 1","cite":"551 U.S. 701","y":2007,"id":"2006/05-915","sc":1,"sum":"By a 5-4 vote, the Court applied a \"strict scrutiny\" framework and found Jefferson County's enrollment plan unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Parker v. Brown","cite":"317 U.S. 341","y":1943,"id":"1940-1955/317us341","sc":1,"sum":"The Court held that the program created by the California Prorate Act of 1933 was a regulation of state industry of local concern that did not impair national control over commerce. The Court noted that states had authority to regulate local matters so long as they did not materially obstruct commerce.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Perry v. Sindermann","cite":"408 U.S. 593","y":1972,"id":"1971/70-36","sc":1,"op":1,"sum":"The Court affirmed the Fifth Circuit and held that Sindermann was entitled to a full trial in federal District Court and a hearing before the Board of Regents. The Court acknowledged that Sindermann did not have a contractual or tenure-based right to continued employment by Odessa Junior College.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Pleva v. Norquist","cite":"35 F. Supp. 2d 839","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/35/839/","by":{"1":"27"}},{"t":"case","label":"Powers v. Ohio","cite":"499 U.S. 400","y":1991,"id":"1990/89-5011","sc":1,"sum":"The Court held that the prosecution is prohibited from excluding an unbiased and qualified juror based on the person’s race regardless of the race of the defendant.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Powers v. Richards","cite":"549 F.3d 505","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/549/505/","by":{"1":"33, 34"}},{"t":"case","label":"Regents of Univ. of Cal. v. Bakke","cite":"438 U.S. 265","y":1978,"id":"1979/76-811","sc":1,"sum":"The Court found that any racial quota for the purpose of admissions supported by a government entity violates the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Roberts v. United States Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Roche v. Lincoln Property Co.","cite":"175 Fed.Appx. 597","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.Appx./175/597/","by":{"1":"47"}},{"t":"case","label":"Rodriguez-Ramos v. Hernandez-Gregorat","cite":"685 F.3d 34","y":2012,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/685/34/","by":{"1":"26"}},{"t":"case","label":"Shell Oil Co. v. Iowa Dept. of Revenue","cite":"488 U.S. 19","y":1988,"id":"1988/87-984","sc":1,"sum":"The OCSLA does not prevent Iowa from including income earned from the sale of OCS oil and gas in its apportionment formula. In adopting for the OCS the civil and criminal laws of \"each adjacent state,\" the OCSLA does provide that \"[s]tate taxation laws shall not apply\" and further specifies that such adoption \"shall never be interpreted as a basis for [a State's] claiming any interest in [the OCS] or the revenues …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Shockency v. Ramsey County","cite":"493 F.3d 941","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/493/941/","by":{"1":"26"}},{"t":"case","label":"Sporhase v. Nebraska ex rel. Douglas","cite":"458 U.S. 941","y":1982,"id":"1981/81-613","sc":1,"op":1,"sum":"A Nebraska statute provides that any person who intends to withdraw ground water from any well located in the State and transport it for use in an adjoining State must obtain a permit from the Nebraska Department of Water Resources. If the Director of Water Resources finds that such withdrawal is reasonable, not contrary to the conservation and use of ground water, and not otherwise detrimental to the public …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Sprietsma v. Mercury Marine, a Div. of Brunswick Corp.","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"State ex rel. New Mexico Judicial Standards Comm’n v. Espinosa","cite":"73 P.3d 197","y":2003,"court":"N.M.","url":"https://www.courtlistener.com/c/P.3d/73/197/","op":1,"by":{"1":"48"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Thomas v. Review Bd. of Indiana Employment Security Div.","cite":"450 U.S. 707","y":1981,"id":"1980/79-952","sc":1,"op":1,"sum":"The Court held that the Review Board's denial of unemployment benefits to Thomas violated his First Amendment right to the free exercise of religion.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Timmons v. Twin Cities Area New Party","cite":"520 U.S. 351","y":1997,"id":"1996/95-1608","sc":1,"sum":"In its 6-to-3 opinion, the majority weighed the character and magnitude of the burden imposed by anti-fusion laws on association rights against Minnesota's stated interest in the necessity of such laws. It upheld Minnesota's interest in ballot integrity and political stability.","sumSrc":"Oyez","by":{"1":"36, 47","2":"8"}},{"t":"case","label":"Tom v. First American Credit Union","cite":"151 F.3d 1289","y":1998,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/1289/","op":7,"ar":5,"by":{"1":"51"}},{"t":"case","label":"Turner v. Fouche","cite":"396 U.S. 346","y":1992,"id":"1969/23","sc":1,"sum":"Appellants, Negro residents of Taliaferro County, Georgia, brought this action to challenge the constitutionality of the statutory system used in Taliaferro and many other Georgia counties to select juries and school boards. The scheme provides for a county school board of five freeholders, which is selected by the grand jury, which in turn is drawn from a jury list selected by the six county jury commissioners, who …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"United States v. Robel","cite":"389 U.S. 258","y":1967,"id":"1967/8","sc":1,"sum":"The Supreme Court held that the provision was overbroad and the war power does not give Congress a blank slate to do whatever it wants. Justice William J. Brennan concurred in the judgment, writing that Congress’ delegation of authority in designating defense facilities to the Secretary of Defense was unconstitutional because they provided no meaningful standards for the Secretary to follow.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Vintson v. Anton","cite":"786 F.2d 1023","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/786/1023/","by":{"1":"30"}},{"t":"case","label":"Watchtower Bible and Tract Society of New York, Inc. v. Village of Stratton","cite":"536 U.S. 150","y":2002,"id":"2001/00-1737","sc":1,"sum":"The Court held that the ordinance's provisions making it a misdemeanor to engage in door-to-door advocacy without first registering with the mayor and receiving a permit violate the First Amendment as it applies to religious proselytizing, anonymous political speech, and the distribution of handbills.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Wilson v. Chicago, Milwaukee, St. Paul, and Pacific R. Co.","cite":"841 F.2d 1347","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/841/1347/","by":{"1":"18"}},{"t":"case","label":"Wrobel v. County of Erie","cite":"692 F.3d 22","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/692/22/","by":{"1":"23"}},{"t":"const","label":"Article VI","clauses":[["supremacy","Supremacy Clause"],["religious-test","No Religious Test Clause"]],"text":"All Debts contracted and Engagements entered into, before the Adoption of this Constitution, shall be as valid against the United States under this Constitution, as under the Confederation. This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding. The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"1":"20"}},{"t":"case","label":"Federal Cases 14 Penn Plaza LLC v. Pyett","cite":"556 U.S. 247","y":2009,"id":"2008/07-581","sc":1,"op":1,"sum":"The Court held that arbitration clauses in employment contracts are enforceable as a matter of federal law.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Am. Commc’ns Ass’n v. Douds","cite":"339 U.S. 382","y":1950,"id":"1940-1955/339us382","sc":1,"sum":"Section 9 (h) of the National Labor Relations Act, as amended b3 the Labor Management Relations Act, 1947, which imposes certain restrictions on, and denies the benefits of certain provisions of the National Labor Relations Act to, any labor organization the officers of which have not filed with the National Labor Relations Board the so-called \"non-Communist\" affidavits prescribed by § 9 (h), is valid under the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Anderson v. Celebrezze","cite":"460 U.S. 780","y":1983,"id":"1982/81-1635","sc":1,"sum":"Ohio's early filing deadline places an unconstitutional burden on the voting and associational rights of petitioner Anderson's supporters.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Bd. of Cty. Comm’rs v. Umbehr","cite":"518 U.S. 668","y":1996,"id":"1995/94-1654","sc":1,"sum":"The Court held that the First Amendment's guarantee of freedom of speech shielded Umbehr, as a government employee, from termination due to things he might have said about the Board. Umbehr successfully proved that his criticisms of the Board preceded his termination and were the primary motivating factor behind its retaliatory termination of his contract.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"sum":"The Court found that that the conditions of confinement did not infringe upon a pretrial detainee's rights. Justice Rehnquist's opinion argued that the issue of prison management is ripe with \"judgment calls\" which rest outside the jurisdiction of the judiciary.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"City of Canton v. Harris","cite":"489 U.S. 378","y":1989,"id":"1988/86-1088","sc":1,"sum":"The Court held that municipalities may be liable for inadequate training of employees, but only when “the failure to train amounts to deliberate indifference” to the constitutional rights of the people with whom the employees will interact. A municipality is then only liable when the failure to train is a deliberate choice on the part of the city.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"City of San Diego v. Roe","cite":"543 U.S. 77","y":2004,"id":"2004/03-1669","sc":1,"sum":"In a unanimous per curiam opinion, the Court held that firing Roe for his behavior and \"speech\" did not violate the First Amendment. Government employers, the Court wrote, could restrict their employees' speech in ways that would be unconstitutional if applied to the general public. But government employees had the right to speak on matters of public concern, such as on government policies of interest to the public.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Connick v. Myers","cite":"461 U.S. 138","y":1983,"id":"1982/81-1251","sc":1,"sum":"The Supreme Court held that speech of public employees is generally only protected when they speak on matters of public concern. Meyers’ speech only dealt with personal and internal office issues. The district court also erred in placing too high of a burden on Connick to show that Meyers’ speech substantially interfered with the operation of the office.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Garcetti v. Ceballos","cite":"547 U.S. 410","y":2006,"id":"2005/04-473","sc":1,"sum":"In a 5-to-4 decision authored by Justice Anthony Kennedy, the Supreme Court held that speech by a public official is only protected if it is engaged in as a private citizen, not if it is expressed as part of the official's public duties.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Heckler v. Campbell","cite":"461 U.S. 458","y":1983,"id":"1982/81-1983","sc":1,"sum":"The Secretary's use of the medical-vocational guidelines to determine a claimant's right to disability benefits does not conflict with the Social Security Act, nor are the guidelines arbitrary or capricious.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Raley v. Hyundai Motor Co.","cite":"642 F.3d 1271","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/642/1271/","by":{"2":"2"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Snowden v. Hughes","cite":"321 U.S. 1","y":1944,"id":"scdb/1943-109","sc":1,"sum":"1. Allegations of a complaint in the federal district court, in substance that the defendants, members of a state board acting as such but in violation of state law, by their failure and refusal to certify correctly the results of a primary, deprived the complainant of nomination and election as a representative in the state assembly, held insufficient to state a cause of action under the Fourteenth Amendment or the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"United Pub. Workers of Am. (CIO) v. Mitchell","cite":"330 U.S. 75","y":1947,"id":"1940-1955/330us75","sc":1,"sum":"The Court held that the Hatch Act does not unconstitutionally restrict the rights of employees of the federal government.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"op":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"U.S. Civil Serv. Comm’n v. Nat’l Ass’n of Letter Carriers","cite":"413 U.S. 548","y":1973,"id":"1972/72-634","sc":1,"sum":"Some individual federal employees, an employees' union, and certain local Democratic and Republican political committees filed this action challenging as unconstitutional on its face the prohibition in § 9 (a) of the Hatch Act, 5 U. S. C. § 7324 (a) (2), against federal employees' taking \"an active part in political management or in political campaigns.\" The section defines the phrase as \"those acts of political …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"Wieman v. Updegraff","cite":"344 U.S. 183","y":1952,"id":"scdb/1952-023","sc":1,"sum":"As thus construed, the Act violates the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"2":"7, 10"}},{"t":"const","label":"Article IV","clauses":[["full-faith-credit","Full Faith and Credit Clause"],["privileges-immunities-iv","Privileges and Immunities Clause"],["fugitive-slave","Fugitive Slave Clause"],["property-clause","Territory and Property Clause"],["guarantee","Guarantee Clause"]],"by":{"2":"3"}}]};